def count_matching(path, text, prefix):
    with open(path, "w", encoding="utf-8") as f:
        f.write(text)
    found = 0
    with open(path, "r", encoding="utf-8") as f:
        for line in f:
            if line.strip().startswith(prefix):
                found = found + 1
    return found
